#!/usr/bin/env python3
"""Generate the @generated modules of crates/crypto/src/p256_group/. Stdlib only, deterministic.
Run: python3 -I scripts/gen_p256_group.py [--check]
--check regenerates into a temp dir and fails on any byte difference from the committed files.
Not trusted: every emitted datum is re-checked by Verus (certificates by compute_only)."""
import filecmp
import json
import math
import sys
import tempfile
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
OUT = Path("crates/crypto/src/p256_group")
HEADER = "// @generated by scripts/gen_p256_group.py — do not edit\n"

P = 2**256 - 2**224 + 2**192 + 2**96 - 1
N = 0xFFFFFFFF00000000FFFFFFFFFFFFFFFFBCE6FAADA7179E84F3B9CAC2FC632551
B = 0x5AC635D8AA3A93E7B3EBBD55769886BC651D06B0CC53B0F63BCE3C3E27D2604B
SMALL = 1 << 16
# Compute chunk sizes: the interpreter's recursion-depth and step budgets scale with --rlimit, and
# every chunk must pass at --rlimit 0.6 (6x under 4). Exponents are split every W bits, trial
# division every SEG candidates.
W = 48
SEG = 32


# ---------------------------------------------------------------------------------------------
# pratt: Pratt certificates for p and n (data: scripts/p256_pratt.json)
# ---------------------------------------------------------------------------------------------


def trial_prime(r):
    return r >= 2 and all(r % d for d in range(2, int(r**0.5) + 2) if d * d <= r)


def load_pratt():
    raw = json.loads((ROOT / "scripts/p256_pratt.json").read_text())
    cert = {int(q): (a, [(int(r), e) for r, e in fs.items()]) for q, (a, fs) in raw.items()}
    assert P in cert and N in cert
    for q, (a, fs) in cert.items():
        assert q >= SMALL and q > 2 and 1 <= len(fs) <= 12
        prod = 1
        for r, e in fs:
            prod *= r**e
            assert (q - 1) % r == 0 and pow(a, (q - 1) // r, q) != 1
            assert r in cert or (r < SMALL and trial_prime(r)), r
        assert prod == q - 1 and pow(a, q - 1, q) == 1
    return cert


def chunks(e):
    """Exponent prefixes e >> (W * i), shortest first, ending at e itself."""
    c = -(-e.bit_length() // W)
    return [e >> (W * (c - 1 - j)) for j in range(c)]


def gen_powmod_chain(name, A, Q, a, q, ex, e, pre, fact, lit):
    """Lemma `name` ensuring `fact`, i.e. `pre` and a fact about powmod(A, ex, Q), with ex == e.
    One compute assert when e has at most W bits, else a chain of W-bit prefix chunks joined by
    `lemma_powmod_ext`; `pre` is checked in the last chunk."""
    if e.bit_length() <= W:
        return f"""proof fn {name}()
    ensures
        {fact},
{{
    assert({fact}) by (compute_only);
}}

"""
    es = chunks(e)
    ms = [pow(a, x, q) for x in es]
    o, calls = [], []
    for j, (x, m) in enumerate(zip(es, ms)):
        last = j == len(es) - 1
        xs = ex if last else f"{x}nat"
        ms_ = lit(m) or f"{m}int"
        if j == 0:
            st = f"powmod({A}, {xs}, {Q} as int) == {ms_}"
        else:
            st = (f"{pre if last else ''}shr({xs}, {W}) == {es[j - 1]}nat && "
                  f"powmod_ext({ms[j - 1]}int, {A}, {xs}, {W}, {Q} as int) == {ms_}")
            calls.append(f"    lemma_powmod_ext({A}, {xs}, {W}, {Q} as int);\n")
        o.append(f"""proof fn {name}_c{j}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.insert(len(calls) - (1 if j else 0), f"    {name}_c{j}();\n")
    o.append(f"""proof fn {name}()
    ensures
        {fact},
{{
{"".join(calls)}}}

""")
    return "".join(o)


def gen_trial(r):
    """Primality of r < 2^16 by trial division, in SEG-candidate chunks joined by `lemma_trial_seg`."""
    d = math.isqrt(r) + 1
    if d - 2 <= SEG:
        return f"""proof fn lemma_trial_{r}()
    ensures
        crate::rsa::is_prime({r}),
{{
    assert(trial_ok({r})) by (compute_only);
    lemma_trial_prime({r});
}}

"""
    bounds = list(range(2, d, SEG)) + [d]
    o, calls = [], []
    for i in reversed(range(len(bounds) - 1)):
        lo, hi = bounds[i], bounds[i + 1]
        st = f"trial_seg({r}, {lo}, {hi})" + (f" && trial_from({r}, {d})" if hi == d else "")
        o.insert(0, f"""proof fn lemma_trial_{r}_c{i}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.append(f"    lemma_trial_{r}_c{i}();\n    lemma_trial_seg({r}, {lo}, {hi});\n")
    o.append(f"""proof fn lemma_trial_{r}()
    ensures
        crate::rsa::is_prime({r}),
{{
{"".join(calls)}    lemma_trial_prime({r});
}}

""")
    return "".join(o)


def gen_pratt():
    cert = load_pratt()
    order = sorted(cert)  # children are smaller than parents, so ascending is leaves-first
    inner = [q for q in order if q not in (P, N)]
    label = {q: str(i) for i, q in enumerate(inner)}
    label[P], label[N] = "P", "N"
    small = sorted({r for _, fs in cert.values() for r, _ in fs if r not in cert})
    o = [HEADER]
    o.append("""//! Pratt certificates for P-256's p and n: each node q has a witness A and the factorization FS
//! of q - 1, checked by `compute_only` one modular power per lemma and assembled into
//! `lucas_ok`; prime factors below 2^16 are checked by trial division.
// Lucas 1876 / Pratt 1975
#![allow(non_snake_case)]
#[allow(unused_imports)]
use super::nt::*;
use vstd::prelude::*;
#[allow(unused_imports)]
use vstd::arithmetic::power::*;

verus! {

""")
    for r in small:
        o.append(gen_trial(r))
    for q in order:
        a, fs = cert[q]
        x = label[q]
        Q, A, FS = f"Q_{x}()", f"A_{x}()", f"FS_{x}()"
        seq = ", ".join(f"({r}nat, {e}nat)" for r, e in fs)
        shape = " && ".join(
            [f"{Q} > 2", f"{FS}.len() == {len(fs)}", f"prod_pow({FS}) == {Q} - 1"]
            + [f"{FS}[{k}].0 == {r}nat" for k, (r, _) in enumerate(fs)]
        )
        full = f"powmod({A}, ({Q} - 1) as nat, {Q} as int) == 1"
        o.append(f"""// ---- node {x}: q = {q}

pub(crate) open spec fn Q_{x}() -> nat {{
    {q}nat
}}

pub(crate) open spec fn A_{x}() -> int {{
    {a}int
}}

pub(crate) open spec fn FS_{x}() -> Seq<(nat, nat)> {{
    seq![{seq}]
}}

proof fn lemma_cert_{x}_shape()
    ensures
        {shape},
{{
    assert({shape}) by (compute_only);
}}

""")
        o.append(gen_powmod_chain(f"lemma_cert_{x}_full", A, Q, a, q, f"({Q} - 1) as nat", q - 1, "",
                                  full, lambda m: "1" if m == 1 else None))
        for k, (r, _) in enumerate(fs):
            rk = f"({FS}[{k}].0 as int)"
            pre = f"{FS}[{k}].0 > 1 && ({Q} - 1) % {rk} == 0"
            fact = f"{pre} && powmod({A}, (({Q} - 1) / {rk}) as nat, {Q} as int) != 1"
            o.append(gen_powmod_chain(f"lemma_cert_{x}_{k}", A, Q, a, q, f"(({Q} - 1) / {rk}) as nat",
                                      (q - 1) // r, pre + " && ", fact, lambda m: None))
        calls = "".join(f"    lemma_cert_{x}_{k}();\n" for k in range(len(fs)))
        o.append(f"""proof fn lemma_cert_{x}()
    ensures
        lucas_ok({Q}, {A}, {FS}),
{{
    lemma_cert_{x}_shape();
    lemma_cert_{x}_full();
{calls}    reveal_with_fuel(lucas_fs_ok, {len(fs) + 1});
}}

""")
        cases = " else ".join(
            f"if i == {k} {{\n            "
            + (f"lemma_prime_{label[r]}();" if r in cert else f"lemma_trial_{r}();")
            + "\n        }"
            for k, (r, _) in enumerate(fs)
        )
        root = q in (P, N)
        flt = (f"""
        forall|x: int|
            x % ({Q} as int) != 0 ==> #[trigger] (pow(x, ({Q} - 1) as nat) % ({Q} as int)) == 1,"""
               if root else "")
        o.append(f"""{"pub(crate) " if root else ""}proof fn lemma_prime_{x}()
    ensures
        crate::rsa::is_prime({Q}),{flt}
{{
    lemma_cert_{x}();
    lemma_cert_{x}_shape();
    assert forall|i: int| 0 <= i < {FS}.len() implies crate::rsa::is_prime(#[trigger] {FS}[i].0) by {{
        {cases}
    }}
    lemma_lucas({Q}, {A}, {FS});
}}

""")
    for x, f in (("p", "p256_p"), ("n", "p256_n")):
        X = x.upper()
        o.append(f"""pub(crate) proof fn lemma_{x}_prime()
    ensures
        crate::rsa::is_prime(crate::p256::{f}() as nat),
{{
    lemma_prime_{X}();
    super::field::lemma_group_consts();
}}

""")
    o[-1] = o[-1].rstrip("\n") + "\n\n} // verus!\n"
    return "".join(o)


# ---------------------------------------------------------------------------------------------
# torsion: g = x^p mod f and a Bezout certificate u f + v (g - x) == 1, f = x^3 - 3x + b
# ---------------------------------------------------------------------------------------------


def qmul(a, b):
    """Mirror of torsion.rs `qmul` (x^3 == 3x - b, x^4 == 3x^2 - b x, mod P)."""
    d0 = a[0] * b[0]
    d1 = a[0] * b[1] + a[1] * b[0]
    d2 = a[0] * b[2] + a[1] * b[1] + a[2] * b[0]
    d3 = (a[1] * b[2] + a[2] * b[1]) % P
    d4 = a[2] * b[2] % P
    return ((d0 - B * d3) % P, (d1 + 3 * d3 - B * d4) % P, (d2 + 3 * d4) % P)


def qpow(a, e):
    """Mirror of torsion.rs `qpow`."""
    if e == 0:
        return (1, 0, 0)
    s = qpow(a, e // 2)
    s = qmul(s, s)
    return qmul(s, a) if e % 2 else s


def ptrim(a):
    a = [c % P for c in a]
    while a and a[-1] == 0:
        a.pop()
    return a


def psub(a, b):
    n = max(len(a), len(b))
    return ptrim([(a[i] if i < len(a) else 0) - (b[i] if i < len(b) else 0) for i in range(n)])


def pmul(a, b):
    r = [0] * max(0, len(a) + len(b) - 1)
    for i, x in enumerate(a):
        for j, y in enumerate(b):
            r[i + j] += x * y
    return ptrim(r)


def pdivmod(a, b):
    a, q, inv = a[:], [0] * max(1, len(a) - len(b) + 1), pow(b[-1], -1, P)
    while len(a) >= len(b):
        c, k = a[-1] * inv % P, len(a) - len(b)
        q[k] = c
        a = ptrim([x - (c * b[i - k] if 0 <= i - k < len(b) else 0) for i, x in enumerate(a)])
    return ptrim(q), a


def xp_chain(q2):
    """lemma_xp_mod_f: qpow(X, p) == XP_POLY in W-bit prefix chunks joined by `lemma_qpow_ext`."""
    q2p = lambda a: f"({q2(a)})"  # struct literals need parentheses in expressions
    es = chunks(P)
    ms = [qpow((0, 1, 0), x) for x in es]
    o, calls = [], []
    for j, (x, m) in enumerate(zip(es, ms)):
        last = j == len(es) - 1
        xs, mv = ("P_LIT() as nat", "XP_POLY()") if last else (f"{x}nat", q2p(m))
        if j == 0:
            st = f"qpow(X(), {xs}) == {mv}"
        else:
            st = f"shr({xs}, {W}) == {es[j - 1]}nat && qpow_ext({q2p(ms[j - 1])}, X(), {xs}, {W}) == {mv}"
        o.append(f"""proof fn lemma_xp_c{j}()
    ensures
        {st},
{{
    assert({st}) by (compute_only);
}}

""")
        calls.append(f"    lemma_xp_c{j}();\n" + (f"    lemma_qpow_ext(X(), {xs}, {W});\n" if j else ""))
    return "".join(o) + f"""pub(crate) proof fn lemma_xp_mod_f()
    ensures
        qpow(X(), P_LIT() as nat) == XP_POLY(),
{{
{"".join(calls)}}}
"""


def gen_torsion():
    g = qpow((0, 1, 0), P)
    f = ptrim([B, -3, 0, 1])
    h = ptrim([g[0], g[1] - 1, g[2]])
    # extended Euclid on (f, h)
    r0, r1, s0, s1, t0, t1 = f, h, [1], [], [], [1]
    while r1:
        q, r = pdivmod(r0, r1)
        r0, r1, s0, s1, t0, t1 = r1, r, s1, psub(s0, pmul(q, s1)), t1, psub(t0, pmul(q, t1))
    assert len(r0) == 1, "gcd(f, x^p - x) is not constant: f has a root mod p"
    c = pow(r0[0], -1, P)
    u, v = ptrim([x * c for x in s0]), ptrim([x * c for x in t0])
    assert len(u) <= 2 and len(v) <= 3
    assert psub(pmul(u, f), psub([1], pmul(v, h))) == []
    u, v = (u + [0, 0])[:2], (v + [0, 0, 0])[:3]
    assert qmul(tuple(v), tuple((h + [0, 0, 0])[:3])) == (1, 0, 0)  # v == 1 / (g - x) mod f
    q2 = lambda a: f"Q2 {{ c0: {a[0]}int, c1: {a[1]}int, c2: {a[2]}int }}"
    return HEADER + f"""//! The torsion certificate: g = x^p mod (f, p) and Bezout polynomials u, v with
//! u f + v (g - x) == 1 mod p, f = x^3 - 3x + b, both checked by `compute_only`.
#![allow(non_snake_case)]
#[allow(unused_imports)]
use super::field::*;
#[allow(unused_imports)]
use super::nt::*;
#[allow(unused_imports)]
use super::torsion::*;
use vstd::prelude::*;

verus! {{

/// x^p mod (f, p).
pub(crate) open spec fn XP_POLY() -> Q2 {{
    {q2(g)}
}}

pub(crate) open spec fn U() -> (int, int) {{
    ({u[0]}int, {u[1]}int)
}}

pub(crate) open spec fn V() -> Q2 {{
    {q2(v)}
}}

{xp_chain(q2)}
pub(crate) proof fn lemma_bezout_cert()
    ensures
        bez_ok(U(), V(), XP_POLY()),
{{
    assert(bez_ok(U(), V(), XP_POLY())) by (compute_only);
}}

}} // verus!
"""


GENERATORS = {"pratt.rs": gen_pratt, "torsion_cert.rs": gen_torsion}


def main():
    check = sys.argv[1:] == ["--check"]
    assert sys.argv[1:] in ([], ["--check"]), "usage: gen_p256_group.py [--check]"
    with tempfile.TemporaryDirectory() as tmp:
        dest = Path(tmp) if check else ROOT / OUT
        for name, gen in GENERATORS.items():
            (dest / name).write_text(gen(), encoding="utf-8")
        if check:
            bad = [n for n in GENERATORS if not filecmp.cmp(dest / n, ROOT / OUT / n, shallow=False)]
            if bad:
                sys.exit(f"gen_p256_group.py --check: stale: {', '.join(bad)}")
            print(f"gen_p256_group.py --check: {len(GENERATORS)} file(s) up to date")


if __name__ == "__main__":
    main()
